@MainActor
final class АдаптерГеометрии: NSObject, NSApplicationDelegate, NSWindowDelegate {
  private let ширинаПунктов = 320
  private let высотаПунктов = 240
  private let новаяШирина = 400
  private let новаяВысота = 300
  private let изменитьЧерезМс = 600
  private let закрытьЧерезМс = 2200
  private let экземпляр = UUID().uuidString
  private let поколение = 1
  private var редакция = 0
  private var числоСигналов = 0
  private var числоВыводов = 0
  private var удержано = false
  private var закрытиеНачато = false
  private var кодЗавершения: Int32 = 0
  private var приём: ЖивойПриём?
  private var завершено = false
  private var готово = false
  private var запросОтправлен = false
  private var последнийСнимок: Снимок?
  private var окно: NSWindow?
  private var полотно: NSView?
  private let слой = CAMetalLayer()
  private var очередь: (any MTLCommandQueue)?
  private var конвейер: (any MTLRenderPipelineState)?
  private var таймер: Timer?
  private var таймерРазмера: Timer?

  private struct Снимок: Equatable {
    let экземпляр: String
    let поколение: Int
    let редакция: Int
    let рамка: NSRect
    let границы: NSRect
    let масштаб: CGFloat
    let запрошеноПикселей: CGSize
    let поверхностьПикселей: CGSize
  }

  private func прямоугольник(_ прямоугольникВхода: NSRect) -> [String: Double] {
    ["абсцисса": Double(прямоугольникВхода.origin.x), "ордината": Double(прямоугольникВхода.origin.y),
     "ширина": Double(прямоугольникВхода.width), "высота": Double(прямоугольникВхода.height)]
  }

  private func снимок() -> Снимок? {
    guard let окно, let полотно else { return nil }
    let рамка = окно.frame
    let границы = полотно.bounds
    let масштаб = окно.backingScaleFactor
    let пиксели = полотно.convertToBacking(границы).size
    let поверхность = слой.drawableSize
    let числа = [рамка.origin.x, рамка.origin.y, рамка.width, рамка.height,
                 границы.origin.x, границы.origin.y, границы.width, границы.height,
                 масштаб, пиксели.width, пиксели.height, поверхность.width, поверхность.height]
    guard числа.allSatisfy({ $0.isFinite }) else { return nil }
    return Снимок(экземпляр: экземпляр, поколение: поколение, редакция: редакция,
                  рамка: рамка, границы: границы, масштаб: масштаб,
                  запрошеноПикселей: пиксели, поверхностьПикселей: поверхность)
  }

  private func аварийно() -> Never {
    let д = Data("{\"схема\":\"fum.ошибка-живой-геометрии.1\",\"код\":\"предел-или-сбой-вывода\",\"эффектыРазрешены\":false}\n".utf8)
    try? FileHandle.standardError.write(contentsOf:д); exit(1)
  }
  private func вывести(_ запись: [String:Any]) -> Bool {
    guard числоВыводов < 32, JSONSerialization.isValidJSONObject(запись),
      var д = try? JSONSerialization.data(withJSONObject:запись,options:[.sortedKeys,.withoutEscapingSlashes]),
      д.count <= 16383 else { return false }
    д.append(10)
    do { try FileHandle.standardOutput.write(contentsOf:д) } catch { return false }
    числоВыводов += 1; return true
  }
  private func срезПриёма() -> ЖивойПриём.Срез? {
    guard let с = снимок(), с.масштаб == 2,
      с.поверхностьПикселей.width >= 0, с.поверхностьПикселей.height >= 0,
      с.поверхностьПикселей.width <= 2048, с.поверхностьПикселей.height <= 2048,
      с.поверхностьПикселей.width.rounded(.towardZero) == с.поверхностьПикселей.width,
      с.поверхностьПикселей.height.rounded(.towardZero) == с.поверхностьПикселей.height else { return nil }
    return ЖивойПриём.Срез(экземпляр:экземпляр,поколение:поколение,редакция:редакция,
      ширина:Int(с.поверхностьПикселей.width),высота:Int(с.поверхностьПикселей.height),
      закрыто:завершено || закрытиеНачато || удержано)
  }
  @discardableResult
  private func сигнал(_ событие: String, _ с: Снимок? = nil,
                      изменилось: Bool = false, запрос: Bool = false) -> ЖивойПриём.Кандидат? {
    guard числоСигналов < 6 else { аварийно() }
    let номер = числоСигналов + 1
    var запись: [String: Any] = [
      "схема":"fum.сигнал-геометрии-окна.1","событие":событие,"экземпляр":экземпляр,
      "поколение":поколение,"редакция":редакция,"номерСигнала":номер,
      "предъявлениеПодтверждено":false,"геометрияИзменена":изменилось
    ]
    if let с {
      запись["рамкаПунктов"] = прямоугольник(с.рамка)
      запись["границыПунктов"] = прямоугольник(с.границы)
      запись["масштабПодложки"] = Double(с.масштаб)
      запись["размерПодложкиПикселей"] = ["ширина":Double(с.запрошеноПикселей.width),"высота":Double(с.запрошеноПикселей.height)]
      запись["размерПоверхностиПикселей"] = ["ширина":Double(с.поверхностьПикселей.width),"высота":Double(с.поверхностьПикселей.height)]
    }
    if let окно { запись["номерОкна"] = окно.windowNumber }
    if запрос { запись["запросРазмераПунктов"] = ["ширина":новаяШирина,"высота":новаяВысота] }
    guard вывести(запись) else { аварийно() }
    числоСигналов = номер
    guard let приём else { отказ("нет-приёмника"); return nil }
    let ответ = приём.принять(запись,номер:номер,редакция:редакция,
      текущий:{ self.срезПриёма() },вывести:{ self.вывести($0) })
    guard ответ.принят else {
      кодЗавершения = 1
      if !закрытиеНачато { отказ(ответ.код ?? "удержание-приёма") }
      return nil
    }
    return ответ.кандидат
  }

  private func отказ(_ код: String) {
    guard !завершено else { return }
    удержано = true; готово = false; кодЗавершения = 1; приём?.удержать()
    таймер?.invalidate(); таймерРазмера?.invalidate()
    guard вывести(["схема":"fum.диагностика-живого-окна.1","код":код,
      "номерПоследнегоНативногоСигнала":числоСигналов,"эффектыРазрешены":false]) else { аварийно() }
    if закрытиеНачато { return }
    guard let окно else { exit(1) }
    закрытиеНачато = true; окно.close()
    if !завершено { exit(1) }
  }

  private func допустим(_ с: Снимок) -> Bool {
    let п = с.запрошеноПикселей
    let д = с.поверхностьПикселей
    return !завершено && !удержано && готово && с.экземпляр == экземпляр &&
      с.поколение == поколение && с.редакция == редакция && с.масштаб == 2 &&
      с.границы.width > 0 && с.границы.height > 0 &&
      п.width > 0 && п.height > 0 && п.width <= 2048 && п.height <= 2048 &&
      д.width == п.width.rounded(.up) && д.height == п.height.rounded(.up) &&
      д.width <= 2048 && д.height <= 2048
  }

  private func тотЖе(_ с: Снимок) -> Bool {
    guard let текущий = снимок() else { return false }
    return с == текущий && допустим(текущий)
  }

  private func обновить(_ событие: String) {
    guard готово && !завершено && !удержано && числоСигналов < 6 else { return }
    guard let окно, let полотно else { отказ("нет-полотна"); return }
    let границы = полотно.bounds
    let пиксели = полотно.convertToBacking(границы).size
    let масштаб = окно.backingScaleFactor
    guard границы.width.isFinite && границы.height.isFinite &&
          границы.width >= 0 && границы.height >= 0 &&
          границы.width <= 640 && границы.height <= 480 &&
          масштаб.isFinite && масштаб > 0 &&
          пиксели.width.isFinite && пиксели.height.isFinite &&
          пиксели.width >= 0 && пиксели.height >= 0 &&
          пиксели.width <= 2048 && пиксели.height <= 2048 else {
      отказ("геометрия-вне-профиля"); return
    }
    CATransaction.begin()
    CATransaction.setDisableActions(true)
    слой.frame = границы
    слой.contentsScale = масштаб
    if пиксели.width > 0 && пиксели.height > 0 {
      слой.drawableSize = CGSize(width: пиксели.width.rounded(.up),
                                 height: пиксели.height.rounded(.up))
    }
    CATransaction.commit()
    guard let до = снимок() else { отказ("геометрия-не-конечна"); return }
    let изменилось: Bool
    if let п = последнийСнимок {
      изменилось = п.рамка != до.рамка || п.границы != до.границы ||
        п.масштаб != до.масштаб || п.запрошеноПикселей != до.запрошеноПикселей ||
        п.поверхностьПикселей != до.поверхностьПикселей
    } else { изменилось = true }
    if изменилось {
      guard редакция < 1_000_000 else { отказ("предел-редакций"); return }
      редакция += 1
    }
    guard let с = снимок() else { отказ("геометрия-не-конечна"); return }
    последнийСнимок = с
    guard let кандидат = сигнал(событие, с, изменилось: изменилось),
      числоСигналов < 6 && допустим(с) else { return }
    нарисовать(с, кандидат)
  }

  private func нарисовать(_ с: Снимок, _ кандидат: ЖивойПриём.Кандидат) {
    guard числоСигналов < 6 && тотЖе(с), let приём,
      приём.разрешён(кандидат,текущий:срезПриёма()), let очередь, let конвейер else { отказ("нет-текущего-кандидата"); return }
    guard let поверхность = слой.nextDrawable() else { отказ("нет-поверхности"); return }
    guard тотЖе(с), приём.разрешён(кандидат,текущий:срезПриёма()),
      поверхность.texture.width == Int(с.поверхностьПикселей.width),
      поверхность.texture.height == Int(с.поверхностьПикселей.height) else { отказ("снимок-изменился"); return }
    guard let команды = очередь.makeCommandBuffer() else { отказ("нет-буфера-команд"); return }
    let проход = MTLRenderPassDescriptor()
    проход.colorAttachments[0].texture = поверхность.texture
    проход.colorAttachments[0].loadAction = .clear; проход.colorAttachments[0].storeAction = .store
    проход.colorAttachments[0].clearColor = MTLClearColorMake(0,0,0,1)
    guard let кодировщик = команды.makeRenderCommandEncoder(descriptor:проход) else { отказ("нет-кодировщика"); return }
    кодировщик.setRenderPipelineState(конвейер); кодировщик.setCullMode(.none)
    кодировщик.drawPrimitives(type:.triangle,vertexStart:0,vertexCount:3); кодировщик.endEncoding()
    guard числоСигналов < 6 && тотЖе(с),
      поверхность.texture.width == Int(с.поверхностьПикселей.width),
      поверхность.texture.height == Int(с.поверхностьПикселей.height),
      приём.погасить(кандидат,текущий:срезПриёма()) else { отказ("снимок-изменился-перед-предъявлением"); return }
    команды.present(поверхность); команды.commit()
    сигнал("предъявление-запрошено",с)
  }

  func applicationDidFinishLaunching(_ уведомление: Notification) {
    let т = Timer(timeInterval: TimeInterval(закрытьЧерезМс) / 1000, target: self,
                  selector: #selector(истёкСрок(_:)), userInfo: nil, repeats: false)
    таймер = т
    RunLoop.main.add(т, forMode: .common)
    let р = Timer(timeInterval: TimeInterval(изменитьЧерезМс) / 1000, target: self,
                  selector: #selector(изменитьРазмер(_:)), userInfo: nil, repeats: false)
    таймерРазмера = р
    RunLoop.main.add(р, forMode: .common)
    guard CommandLine.arguments.count == 4,
          CommandLine.arguments.dropFirst().allSatisfy({ $0.hasPrefix("/") }) else {
      отказ("ожидались-три-абсолютных-пути")
      return
    }
    let адрес = URL(fileURLWithPath: CommandLine.arguments[1])
    guard адрес.pathExtension == "metallib",
          let устройство = MTLCreateSystemDefaultDevice(),
          let очередь = устройство.makeCommandQueue() else {
      отказ("нет-библиотеки-или-устройства")
      return
    }
    do {
      let библиотека = try устройство.makeLibrary(URL: адрес)
      guard let вершина = библиотека.makeFunction(name: "вершинаЦвета"),
            let фрагмент = библиотека.makeFunction(name: "фрагментЦвета") else {
        отказ("нет-функций-цвета")
        return
      }
      let описание = MTLRenderPipelineDescriptor()
      описание.vertexFunction = вершина
      описание.fragmentFunction = фрагмент
      описание.colorAttachments[0].pixelFormat = .bgra8Unorm
      конвейер = try устройство.makeRenderPipelineState(descriptor: описание)
      self.очередь = очередь
      слой.device = устройство
      слой.pixelFormat = .bgra8Unorm
      слой.framebufferOnly = true
      слой.maximumDrawableCount = 2
      слой.allowsNextDrawableTimeout = true
      слой.presentsWithTransaction = false
      let рамка = NSRect(x: 0, y: 0, width: CGFloat(ширинаПунктов), height: CGFloat(высотаПунктов))
      let окно = NSWindow(contentRect: рамка, styleMask: [.titled, .closable, .resizable],
                          backing: .buffered, defer: false)
      окно.isReleasedWhenClosed = false
      окно.title = "FUMA · Metal · Живой приём"
      окно.contentMaxSize = NSSize(width: 640, height: 480)
      let полотно = NSView(frame: рамка)
      полотно.autoresizingMask = [.width, .height]
      полотно.wantsLayer = true
      полотно.layer = слой
      окно.contentView = полотно
      окно.delegate = self
      self.окно = окно
      self.полотно = полотно
      приём = try ЖивойПриём(экземпляр:экземпляр,поколение:поколение,
        приёмникПуть:CommandLine.arguments[2],планПуть:CommandLine.arguments[3])
      окно.center()
      окно.makeKeyAndOrderFront(nil)
      готово = true
      обновить("открыто")
    } catch {
      отказ("подготовка-библиотеки-окна-или-FUMA")
    }
  }

  func windowDidResize(_ уведомление: Notification) {
    guard let источник = уведомление.object as? NSWindow,
          let окно, источник === окно else { return }
    обновить("размер-изменён")
  }
  func windowDidChangeBackingProperties(_ уведомление: Notification) {
    guard let источник = уведомление.object as? NSWindow,
          let окно, источник === окно else { return }
    обновить("подложка-изменена")
  }

  @objc private func изменитьРазмер(_ событиеТаймера: Timer) {
    guard !завершено && !запросОтправлен else { return }
    guard готово, let окно, числоСигналов < 6 else {
      отказ("запрос-без-готового-окна"); return
    }
    запросОтправлен = true
    таймерРазмера?.invalidate()
    сигнал("изменение-размера-запрошено", запрос: true)
    guard !завершено else { return }
    окно.setContentSize(NSSize(width: CGFloat(новаяШирина), height: CGFloat(новаяВысота)))
  }

  @objc private func истёкСрок(_ таймерСобытия: Timer) {
    guard !завершено else { return }
    if let окно { окно.close() } else { отказ("срок-без-окна") }
  }

  func windowWillClose(_ уведомление: Notification) {
    guard !завершено, let источник = уведомление.object as? NSWindow,
      let окно, источник === окно else { return }
    закрытиеНачато = true; завершено = true; готово = false
    таймер?.invalidate(); таймерРазмера?.invalidate()
    редакция += 1
    сигнал("закрыто",снимок())
    exit(кодЗавершения)
  }
}

